import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav className="bg-white/80 backdrop-blur-md shadow-md sticky top-0 z-50">
      <div className="container mx-auto px-4">
        <div className="flex justify-between items-center py-4">
          <Link to="/" className="text-2xl font-bold text-forest-green">
            Jharkhand Explorer
          </Link>
          <div className="flex items-center space-x-6">
            <Link to="/explore" className="text-stone-gray hover:text-leaf-green font-medium">
              Explore
            </Link>
            <Link to="/marketplace" className="text-stone-gray hover:text-leaf-green font-medium">
              Marketplace
            </Link>
            <Link to="/login" className="bg-leaf-green text-white px-4 py-2 rounded-md hover:bg-forest-green font-semibold transition duration-300">
              Login
            </Link>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
